function fx(events){for(let [index,e]of events.entries())schedule(()=>{if(e.kind==='hit'||e.kind==='wolf'){let enemy=state.enemies.find(x=>x.id===e.target);document.querySelector(`.actor.${e.target}`)?.classList.add('hit');float(left(enemy.pos),e.amount,e.kind==='wolf'?'wolf-num':'');tone('hit')}else if(e.kind==='hurt'){float(left(state.pos),e.amount,'hero-num');if(e.amount){document.querySelector('.arena').classList.add('shake');tone('hurt')}}else if(e.kind==='heal'){float(left(state.pos),3,'heal-num')}},index*150);schedule(()=>document.querySelector('.arena').classList.remove('shake'),700)}
function float(x,amount,cls){let el=document.createElement('span');el.className=`float-number ${cls}`;el.style.setProperty('--x',x+'%');el.textContent=cls==='heal-num'?`+${num(amount)}`:amount?`−${num(amount)}`:'اتّقاء';$('combat-fx').append(el);schedule(()=>el.remove(),1300)}
function act(index,target){if(busy)return;let result=play(state,index,target);if(result.error)return toast(result.error);resetSelection();render();fx(result.events);if(state.phase==='victory')schedule(showResult,650)}
$('hand').addEventListener('click',e=>{let b=e.target.closest('[data-index]');if(!b||busy||state.phase!=='battle')return;let index=Number(b.dataset.index);tone('select');if(mode==='leap'){selected=index;destination=null}else{mode=null;destination=null;selected=selected===index?null:index}render()});
$('positions').onclick=e=>{let b=e.target.closest('[data-position]');if(!b||busy||mode!=='leap'||selected===null)return;destination=Number(b.dataset.position);render()};
$('leap').onclick=()=>{if(busy)return;if(mode==='leap')resetSelection();else{resetSelection();mode='leap'}render()};
$('drink').onclick=()=>{if(busy)return;let current=mode;resetSelection();if(current!=='drink')mode='drink';render()};
$('exert').onclick=()=>{if(busy)return;let current=mode;resetSelection();if(current!=='exert')mode='exert';render()};
$('cancel-action').onclick=()=>{resetSelection();render()};
$('confirm-action').onclick=()=>{if(busy||state.phase!=='battle')return;let result;if(mode==='leap')result=leap(state,selected,destination);else if(mode==='drink')result=drink(state);else if(mode==='exert')result=exert(state)?{events:[]}:{error:'تجلّدتَ هذا الدور'};else if(selected!==null)return act(selected);else return;if(result.error)return toast(result.error);resetSelection();render();fx(result.events);tone('select')};
function enemyClick(e){let b=e.target.closest('[data-enemy]');if(!b||busy)return;let enemy=state.enemies.find(x=>x.id===b.dataset.enemy);if(mode==='leap')return toast('اختر بطاقة لطرحها، ثم موضعًا في الشريط أسفل الساحة.');if(selected!==null&&!mode&&targets(CARDS[state.hand[selected]]))return act(selected,enemy.id);let i=intent(state,enemy),f=forecast(state).find(x=>x.id===enemy.id);showModal(`<span class="eyebrow">اقرأ خصمك</span><h2 id="modal-title">${enemy.name}</h2><p>الصحة: <bdi dir="ltr">${num(enemy.hp)} / ${num(enemy.maxHp)}</bdi> · المسافة <b>${num(distance(state,enemy))}</b>.</p><p>${state.ruleset==='lure'?`يلتزم بالمواضع ${i.cells.map(p=>num(p+1)).join('، ')}. التحرك لا يغيّر هدفه. دفعه خارج موضعه يربك الهجوم.${enemy.exposed?' مكشوف بعد اندفاعة فائتة.':''}${isolated(state,enemy)?' معزول عن رفيقه.':' رفيقه يحميه من السِّيد.'}`:enemy.id==='guard'?'يتقدّم موضعًا ثم يطعن إن أصبحت المسافة ١.':'يتراجع إن اقتربت منه، ثم يرمي. الصخر يحجب ٣ من السهم.'}<br>النية: <b>${i.label}</b>.<br>الضرر منه بعد اتّقائك: <b>${num(f?.hpLoss||0)}</b>.</p><button class="primary" data-close>عد إلى المواجهة</button>`)}
$('actors').addEventListener('click',enemyClick);$('enemy-panels').addEventListener('click',enemyClick);
$('end-turn').onclick=()=>{if(busy)return;resetSelection();busy=true;let events=endTurn(state);render();fx(events);schedule(()=>{busy=false;render();if(state.phase!=='battle')showResult()},Math.max(650,events.length*150+350))};
$('terrain-status').onclick=()=>showModal(`<span class="eyebrow">اقرأ الأرض</span><h2 id="modal-title">الصخر والرمل</h2><p>الموضعان ١ و٥ نتوءان صخريان: يحجبان ٣ من ضرر الرامي، ويرفعان اتّقاء «أحتمي بالصخر» من ٥ إلى ٨.</p><p>المواضع الوسطى رمل مكشوف. اقرأ الرقم المتوقع للضرر، واستخدم الوثبة لعبور الخصم وتغيير موضعك.</p><button class="primary" data-close>عد إلى المواجهة</button>`);
$('menu-btn').onclick=()=>{let open=$('game-menu').classList.toggle('hidden');$('menu-btn').setAttribute('aria-expanded',String(!open))};
document.addEventListener('click',e=>{if(!e.target.closest('.game-header')){$('game-menu').classList.add('hidden');$('menu-btn').setAttribute('aria-expanded','false')}});
function closeModal(){ $('modal').classList.add('hidden');$('modal').innerHTML='';returnFocus?.focus?.()}
function showModal(html,closable=true){$('game-menu').classList.add('hidden');$('menu-btn').setAttribute('aria-expanded','false');returnFocus=document.activeElement;$('modal').innerHTML=`<div class="modal-panel">${closable?'<button class="modal-close" data-close aria-label="إغلاق">×</button>':''}${html}</div>`;$('modal').classList.remove('hidden');$('modal').querySelector('button')?.focus();$('modal').querySelectorAll('[data-close]').forEach(b=>b.onclick=closeModal)}
function help(){if(state.ruleset==='lure')return trialBrief(true);showModal(`<span class="eyebrow">العَدْو والحيلة</span><h2 id="modal-title">لا تُحاصر يدك</h2><div class="help-row"><span>١</span><p><b>وثبة العَدّاء دائمة.</b> اضغط الوثبة، ثم بطاقة لطرحها، ثم موضعًا مضاءً، ثم «اثب» لتأكيد الحركة. تتجاوز الخصوم حتى ٣ مواضع، مقابل ١ إجهاد وبلا طاقة. مرة كل دور؛ يمكنك طرح الوَهَن.</p></div><div class="help-row"><span>٢</span><p><b>القوس أداة اشتباك أيضًا.</b> حدّد البطاقة لتقرأ نتيجتها على لوحة كل خصم، ثم اضغط الخصم للتنفيذ. من قريب يتحوّل السهم إلى ضربة بالمقبض بضرر أقل، وتدفع الخصم إن خلفه فراغ. الوتر المشدود يحتاج الثبات للرمي فقط.</p></div><div class="help-row"><span>٣</span><p><b>لك في الصخر ستر.</b> موضعا طرف الوادي صخريان؛ يحجبان ٣ من هجوم الرامي، ويزيدان اتّقاء «أحتمي بالصخر» من ٥ إلى ٨. اقرأ الضرر المتوقع في الشريط تحت الساحة قبل إنهاء دورك.</p></div><div class="help-row"><span>٤</span><p><b>السِّيد يقرأ أثرك.</b> تحرّك ثم اضرب، أو علّم خصمًا بـ«اقتفاء الأثر» ثم اضربه. ينقضّ الذئب بـ٥ ضرر إضافي، مرة في الدور، إذا بقي الهدف حيًا.</p></div><div class="help-row"><span>٥</span><p><b>للجسد حدّ وللماء ثمن.</b> التجلّد يمنح ٢ طاقة مقابل ٢ إجهاد. كل زيادة إجهاد تنتهي عند ٤ أو أكثر تضيف وَهَنًا. رشفة القِربة تستهلك ١ طاقة، وتعيد ٣ صحة وتزيل ٣ إجهاد، مرة في الدور حتى ينفد الماء.</p></div><p>٣ طاقة و٥ بطاقات كل دور. الاتّقاء يتلاشى عند بداية دورك. لا مؤقت. تُحفظ محاولتك تلقائيًا، بما فيها محاولات النسخة السابقة.</p><button class="primary" data-close>إلى المورد</button>`)}
$('help').onclick=help;$('sound').onclick=()=>{sound=!sound;try{localStorage.setItem('shanfara.sound',String(sound))}catch{}render();tone('select')};
$('route-info').onclick=()=>showModal(`<span class="eyebrow">دربك إلى المورد</span><h2 id="modal-title">${APPROACHES[state.approach]?.name}</h2><p>${APPROACHES[state.approach]?.desc}</p><p>مجموعة الرحلة تضم المهارات نفسها؛ يتغيّر موضع البداية والبطاقات الخمس الأولى حسب الدرب.</p>${state.boon?`<p><b>غنيمتك: ${BOONS[state.boon].name}</b><br>${BOONS[state.boon].text}${state.boonUsed?' (استُخدمت)':''}</p>`:''}<button class="primary" data-close>عد إلى المواجهة</button>`);
function begin(approach){if(approach==='lure'&&state.ruleset!=='lure'){try{localStorage.setItem('shanfara.classic.backup',JSON.stringify(state))}catch{}}epoch++;state=fresh(Date.now()>>>0,approach,boon);if(approach==='lure')state.attemptId=String(Date.now());resetSelection();busy=false;closeModal();render();toast(`${APPROACHES[approach].name}… بدأ الأثر.`)}
function routeChoice(first=false){showModal(`<span class="eyebrow">الشَّنْفَرَى · مورد الظلال</span><h2 id="modal-title">من أيّ دربٍ تأتي؟</h2><p>${first?'عند المورد متعقّب ورامٍ، وإلى جانبك السِّيد. أسقط الخصمين وابقَ حيًا.':'اختر دربًا لمحاولة جديدة. ستتغير يد البداية وموضعك.'}</p><div class="routes">${Object.entries(APPROACHES).map(([id,r])=>`<button class="route" data-route="${id}">${icon(r.icon)}<div><strong>${r.name}</strong><small>${r.desc}</small><span>${r.hand.map(c=>CARDS[c].name).join(' · ')}</span></div><b>←</b></button>`).join('')}</div>${boon?`<p class="boon-note">غنيمة محفوظة: <b>${BOONS[boon].name}</b> — ${BOONS[boon].text}</p>`:''}<button class="secondary" id="route-help">كيف ألعب؟</button>`,!first);$('modal').querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>b.dataset.route==='lure'?trialBrief():begin(b.dataset.route));$('route-help').onclick=()=>{help();let button=$('modal').querySelector('.primary');button.textContent='اختر دربك';button.onclick=()=>routeChoice(first)}}
$('restart').onclick=()=>showModal(`<span class="eyebrow">رحلة جديدة</span><h2 id="modal-title">تعود إلى أول الأثر؟</h2><p>ستبدأ المواجهة من جديد. غنيمة الرحلة السابقة تبقى، وتُستبدل محاولتك الحالية عند اختيار الدرب.</p><button class="primary" id="confirm-restart">اختر دربًا جديدًا</button><button class="secondary" data-close>أكمل المواجهة</button>`);document.addEventListener('click',e=>{if(e.target.id==='confirm-restart')routeChoice()});
$('journal').onclick=()=>showModal(`<span class="eyebrow">الأثر الباقي</span><h2 id="modal-title">سجلّ المواجهة</h2><ol class="journal">${state.log.map(t=>`<li>${t}</li>`).join('')}</ol><button class="primary" data-close>عد إلى المواجهة</button>`);
$('deck-info').onclick=()=>{let all=[...state.deck,...state.hand,...state.discard],counts={};all.forEach(c=>counts[c]=(counts[c]||0)+1);showModal(`<span class="eyebrow">مجموعة الشنفرى</span><h2 id="modal-title">رزمة الرحلة</h2><p>السحب: ${num(state.deck.length)} · اليد: ${num(state.hand.length)} · المطروح: ${num(state.discard.length)}</p>${state.ruleset==='lure'?`<p>خرجت لبقية المواجهة: <b>${state.exhaust.map(id=>CARDS[id].name).join('،')||'لا شيء بعد'}</b></p>`:''}<div class="deck-scroll">${Object.entries(counts).map(([id,n])=>`<div class="deck-list"><span>${CARDS[id].name}</span><span>× ${num(n)}</span></div>`).join('')}</div><button class="primary" data-close>عد إلى المواجهة</button>`)};
function showResult(){if(state.phase==='battle')return;let win=state.phase==='victory';if(win&&state.reward)return showEpilogue();showModal(`<span class="eyebrow">${win?'المورد لك ولأهلك':'للصحراء ذاكرة'}</span><h2 id="modal-title">${win?'نجوتَ… ولم تكن وحدك':'انقطع الأثر'}</h2><p>${win?(state.ruleset==='lure'?'أكملت الموقف. قارن افتتاحيتك، أو جرّب خطة أخرى بنفس اليد.':'سكن الوادي، وانحنى الذئب إلى الماء. اختر غنيمة تحمل أثرها في محاولتك التالية.'):'إذا أغلق المتعقّب الطريق، اثب فوقه أو ادفعه بمقبض القوس. الصخر يحجب الرمي، والرمل يمنحك حيلة عند الاشتباك.'}</p><div class="result-stats"><span><b>${num(state.turn)}</b>أدوار</span><span><b>${num(state.played)}</b>بطاقات لُعبت</span><span><b>${num(state.hp)}</b>صحة باقية</span></div>${state.ruleset==='lure'?`<p>تلقّيت ${num(state.damageTaken)} ضرر، وتخلّيت عن ${num(state.exhaust.length)} بطاقة. جرّب افتتاحية أخرى بنفس اليد لتقارن أثرها.</p><button class="primary" id="trial-again">جرّب خطة أخرى بنفس اليد</button><button class="secondary" id="trial-compare">قارن افتتاحيتك</button>`:win?`<div class="rewards">${Object.entries(BOONS).map(([id,b])=>`<button class="reward" data-reward="${id}">${icon(id)}<strong>${b.name}</strong><small>${b.text}</small></button>`).join('')}</div>`:'<button class="primary" id="retry">اختر دربًا وحاول مجددًا</button>'}`,false);$('trial-again')?.addEventListener('click',()=>begin('lure'));$('trial-compare')?.addEventListener('click',showTrialReport);$('retry')?.addEventListener('click',()=>routeChoice());$('modal').querySelectorAll('[data-reward]').forEach(b=>b.onclick=()=>{state.reward=b.dataset.reward;boon=state.reward;try{localStorage.setItem('shanfara.boon',boon)}catch{}save();showEpilogue()})}
function showEpilogue(){let reward=BOONS[state.reward];showModal(`<span class="eyebrow">اكتملت المواجهة</span><h2 id="modal-title">إلى ما وراء الوادي</h2><p class="intro-verse">ولي دونكم أهلون…</p><p>حملتَ <b>${reward?.name||'زاد الرحلة'}</b>، وترك الذئب أثره إلى جوار أثرك.</p><p>${reward?.text||''} تظهر فائدتها عند بدء محاولة جديدة، ويمكنك تجربة درب آخر.</p><button class="primary" id="again">اختر دربًا جديدًا</button><button class="secondary" data-close>استعرض ساحة القتال</button>`);$('again').onclick=()=>routeChoice()}
$('modal').addEventListener('keydown',e=>{if(e.key==='Escape'&&$('modal').querySelector('[data-close]'))closeModal();if(e.key==='Tab'){let a=[...$('modal').querySelectorAll('button:not(:disabled),a[href]')],first=a[0],last=a.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('modal').classList.contains('hidden')){resetSelection();$('game-menu').classList.add('hidden');$('menu-btn').setAttribute('aria-expanded','false');render()}});


function trialHistory(){try{let h=JSON.parse(localStorage.getItem('shanfara.lure.history')||'[]');return Array.isArray(h)?h.filter(r=>r&&r.report&&Array.isArray(r.report.enemies)&&Array.isArray(r.report.burned)).slice(-5):[]}catch{return []}}
function classicBackup(){try{return restore(JSON.parse(localStorage.getItem('shanfara.classic.backup')))}catch{return null}}
function recordTrial(){if(state.ruleset!=='lure'||!state.openingReport||!state.attemptId)return;let h=trialHistory();if(h.some(r=>r.id===state.attemptId))return;h.push({id:state.attemptId,report:state.openingReport});try{localStorage.setItem('shanfara.lure.history',JSON.stringify(h.slice(-5)))}catch{}}
function trialBrief(helpOnly=false){showModal(`<span class="eyebrow">الشنفرى · موقف قابل للإعادة</span><h2 id="modal-title">اثبت… أم استدرج؟</h2><p>بداية الموقف: صحة <b>١٨</b> وطاقة <b>٣</b>. الرامي لديه <b>١٣ صحة</b>؛ «وتر مشدود» قادر على إنهائه إذا ثبتَّ.</p><p>المتعقّب يندفع إلى الموضعين <b>١ و٢</b> بـ<b>١١ ضرر</b>. الرامي يغطي المواضع <b>٢ و٣ و٤</b> بـ<b>٦ ضرر</b>. كلاهما يلتزم بالمواضع المعلنة حتى لو تحرّكت.</p><ul class="trial-rules"><li><b>الوثبة تضحية:</b> ١ طاقة وبطاقة قابلة للعب تخرج لبقية المواجهة. الوَهَن لا يصلح ثمنًا، ولا يُضاف إجهاد للوثبة.</li><li><b>السِّيد يطلب فريسة معزولة:</b> افصل الخصمين بأكثر من موضع. إذا أخطأ المتعقّب اندفاعته، يبقى مكشوفًا لضربتك التالية مع الذئب.</li><li><b>الدفع يفسد الهجوم:</b> تغيير موضع الخصم بمقبض القوس يربك خطته المعلنة.</li></ul><p class="trial-legend"><b>م</b> تحت الموضع = يستهدفه المتعقّب · <b>ر</b> = يستهدفه الرامي.</p><p>${helpOnly?'اختر بطاقة واقرأ أثرها على كل خصم. لا تُنفّذ الوثبة حتى تضغط «اثب».':'نفس اليد وترتيب السحب في كل محاولة، بلا غنيمة سابقة. محاولتك الأصلية تُحفظ عند بدء التجربة.'}</p><button class="primary" id="trial-confirm">${helpOnly?'أكمل الموقف':'ابدأ الموقف'}</button><button class="secondary" data-close>عد إلى الساحة</button>`);$('trial-confirm').onclick=()=>helpOnly?closeModal():begin('lure')}
function showTrialReport(){let history=trialHistory();showModal(`<span class="eyebrow">نفس الموقف · خطط مختلفة</span><h2 id="modal-title">ماذا صنعت خطوتك؟</h2><p>هذه نتائج الدور الأول فقط. قارن الصحة، والخصوم الباقين، والبطاقات التي ضحّيت بها؛ ثم جرّب إكمال خطتك.</p><div class="trial-reports">${history.length?history.slice().reverse().map((entry,index)=>{let r=entry.report,guard=r.enemies.find(e=>e.id==='guard');return `<article class="trial-report"><strong>${index===0?'آخر افتتاحية':'افتتاحية سابقة'}</strong><div><span>الصحة <b>${num(r.hpLeft)}</b></span><span>خصوم باقون <b>${num(r.enemies.filter(e=>e.hp>0).length)}</b></span><span>إجهاد <b>${num(r.strain)}</b></span></div><p>تخلّيت عن: <b>${r.burned.map(id=>CARDS[id]?.name||id).join('،')||'لا شيء'}</b><br>المتعقّب: ${guard?.hp===0?'سقط':guard?.exposed?'أخطأ اندفاعه وأصبح مكشوفًا':'نفّذ اندفاعه'}<br>لعبت: ${r.cards.map(id=>CARDS[id]?.name||id).join('،')||'لا بطاقات'}</p></article>`}).join(''):'<p>أكمل الدور الأول في تجربة الاستدراج لتظهر افتتاحيتك هنا.</p>'}</div><button class="primary" id="report-retry">جرّب خطة أخرى بنفس اليد</button><button class="secondary" data-close>أكمل المواجهة</button>`);$('report-retry').onclick=()=>begin('lure')}
$('trial-start').onclick=()=>trialBrief();$('trial-report').onclick=showTrialReport;$('return-classic').onclick=()=>{let old=classicBackup();if(!old)return;epoch++;state=old;resetSelection();busy=false;closeModal();render();if(state.phase!=='battle')showResult();toast('عدت إلى محاولتك السابقة.')};

render();if(new URLSearchParams(globalThis.location?.search||'').get('trial')==='lure'&&state.ruleset!=='lure')trialBrief();else if(state.phase!=='battle')showResult();else if(!resumed)routeChoice(true);
